mapper.update:
UPDATE staff set
	img_path=#{imgPath}
WHERE
	staff_id=#{staffId}

UPDATE staff SET
	shop_id		= #{shopId}
	,staff_name	= #{staffName}
	,position	= #{position}
	,email		= #{email}
	,phone		= #{phone}
WHERE
	staff_id 			= #{staffId}

UPDATE staff SET
	com_id		= #{iNum}
	,staff_name	= #{staffName}
	,position	= #{position}
	,email		= #{email}
	,phone		= #{phone}
WHERE
	staff_id 			= #{staffId}

